-- Mock test for avf/scripts/Immersive_Tank.lua (v2, generated by tools/porting/history/port_immersive.py).
-- Run from the repo root with Lua 5.1:  lua5.1 tools/porting/tests/test_immersive_tank.lua
dofile("tools/porting/tests/mockengine.lua")

local function check(cond, msg) if not cond then error("FAIL: " .. msg, 2) end print("ok  " .. msg) end
local PATH = "avf/scripts/Immersive_Tank.lua"

local env = MockEngine.load(PATH, { preload = MockEngine.includes(PATH) })
env.side = "server"
env.PLAYERS = { [1] = { pos = { 0, 0, 0 }, health = 1 } }
env.ORDER = { 1 }
-- the engine's script/common.lua (included by the script; the mock drops engine includes)
env.clamp = function(v, mi, ma) if v < mi then return mi elseif v > ma then return ma end return v end
local HEALTH = 1
env.def("FindVehicle", function(tag) return tag == "cfg" and 9 or 0 end)
env.def("IsHandleValid", function(h) return h ~= 0 end)
env.def("GetVehicleHealth", function() return HEALTH end)
env.def("GetVehicleTransform", function() return env.Transform({ 0, 0, 0 }) end)
env.def("GetVehicleBody", function() return 109 end)
env.def("FindShapes", function() return {} end)
env.def("FindJoints", function() return {} end)
env.def("FindLocations", function() return {} end)
env.def("FindLocation", function(tag) return tag == "cook_off" and 70 or 0 end)
env.def("GetLocationTransform", function() return env.Transform({ 0, 2, 0 }) end)
env.def("HasTag", function() return false end)
env.def("QueryRaycast", function() return false, 0, { 0, 1, 0 }, 0 end)
env.def("GetBodyTransform", function() return env.Transform({ 0, 0, 0 }) end)
env.def("TransformCopy", function(t) return env.Transform(env.VecCopy(t.pos), t.rot) end)
env.def("GetPlayerHealth", function() return 1 end)
env.def("GetBodyVelocity", function() return { 0, 0, 0 } end)
env.def("GetBodyMass", function() return 1000 end)
env.def("GetBodyCenterOfMass", function() return { 0, 1, 0 } end)
env.def("QueryAabbBodies", function() return {} end)
env.def("QueryAabbShapes", function() return {} end)
env.def("GetTime", function() return 0 end)
env.def("GetTimeStep", function() return 1 / 60 end)

env.server.init()
check(env.tank.id == 9, "server finds its tank")
env.sent = {}
for i = 1, 30 do env.server.tick(1 / 60) end
check(not env.tank.dead and not env.tank.cooking_off, "healthy tank: nothing happens")
HEALTH = 0.5 -- under min_tank_health 0.8: the tank is killed and cooks off
for i = 1, 300 do env.server.tick(1 / 60) end
check(env.tank.cooking_off or env.tank.dead, "damaged tank: cooks off / dies on the server")
local fx, ops = 0, 0
for _, c in ipairs(env.sent) do
	if c.fn == "client.itFx" and c.to == 0 then fx = fx + 1 ops = ops + #c.args[1] end
end
check(fx > 0 and ops > 0, "its visual calls go to every client (" .. fx .. " batches, " .. ops .. " calls)")
-- the effect functions travel as one event each: a cook-off must stay well below the ~178000 recorded calls of the
-- first version (particle setup calls recorded one by one)
check(ops < 5000, "effects sent as events, not particle by particle (" .. ops .. " calls)")
local names = {}
for _, c in ipairs(env.sent) do if c.fn == "client.itFx" then for _, op in ipairs(c.args[1]) do names[op[1]] = true end end end
for n in pairs(names) do
	if n:sub(1, 1) == "@" then check(env.ITR_FX[n:sub(2)] ~= nil, "effect " .. n .. " has a client function") end
end
local drawn = 0
for _, n in ipairs({ "SpawnParticle", "PlaySound", "PlayLoop", "PointLight", "ParticleReset", "ShakeCamera" }) do drawn = drawn + (env.calls[n] or 0) end
check(drawn == 0, "no drawing / particles / sounds on the server")
check(next(env.violations) == nil, "no client-only calls on the server")

-- clients replay them
env.side = "client"
env.def("HasFile", function() return true end)
env.client.init()
local batch
for _, c in ipairs(env.sent) do if c.fn == "client.itFx" then batch = c.args[1] break end end
env.client.itFx(batch)
for _, c in ipairs(env.sent) do if c.fn == "client.itFx" then env.client.itFx(c.args[1]) end end
for i = 1, 60 do env.client.update(1 / 60) end
check((env.calls.SpawnParticle or 0) + (env.calls.PlaySound or 0) + (env.calls.PlayLoop or 0) > 0, "clients replay the visuals")
check(next(env.violations) == nil, "no server-only calls on the client")

-- player damage: only a lethal amount counts (as the original health script)
env.side = "server"
local SET = {}
env.def("FindTriggers", function() return { 300 } end)
env.def("HasTag", function(h, t) return false end)
env.def("GetTagValue", function(h, t) return t == "hitbox" and "TORSO" or "" end)
env.def("IsPlayerHost", function() return true end)
env.def("SetTag", function(h, t, v) SET[h] = v end)
env.IT_HurtPlayer(1, 0.3)
check(SET[300] == nil, "fire damage below the whole health: no effect")
env.IT_HurtPlayer(1, 1.5)
check(SET[300] == 10000, "a lethal amount kills through the torso hitbox")
print("all Immersive_Tank tests passed")
